_address" maxlength="500" autocomplete="street-address" required></div><div class="col-md-6"><label class="form-label" for="toAddress">Moving to</label><input class="form-control" id="toAddress" name="to_address" maxlength="500" required></div><div class="col-md-4"><label class="form-label" for="distanceKm">Distance (km)</label><input class="form-control" id="distanceKm" name="distance_km" type="number" min="0" max="10000" step="0.01" required><div class="form-text">Enter the route distance. Map verification is not configured.</div></div><div class="col-md-4"><label class="form-label" for="floors">Floors to carry</label><input class="form-control" id="floors" name="floors" type="number" min="0" max="100" value="0" required></div><div class="col-md-4"><label class="form-label" for="packing">Packing service</label><select class="form-select" id="packing" name="packing_required"><option value="false">No</option><option value="true">Yes</option></select></div><div class="col-12"><label class="form-label" for="inventory">Inventory <span class="text-secondary">(optional; one item per line: item,quantity)</span></label><textarea class="form-control" id="inventory" rows="3" placeholder="Cartons,4&#10;Table,1"></textarea></div><div class="col-12"><label class="form-label" for="moveMessage">Notes <span class="text-secondary">(optional)</span></label><textarea class="form-control" id="moveMessage" name="message" maxlength="3000" rows="2"></textarea></div></div></div><button class="btn btn-gold btn-lg" type="submit" data-submit><?= e($t('calculate')) ?></button><p class="form-text mt-3">By submitting, you ask RoomShift to contact you about this move. Your details are used to provide and manage this quote.</p><div id="formStatus" class="mt-3" role="status" aria-live="polite"></div></form><section class="quote-result" aria-labelledby="quoteResultTitle"><p class="eyebrow">Your quote</p><h2 id="quoteResultTitle" class="h3">Calculated securely</h2><div id="quoteResult" class="text-secondary">Your itemized quote will appear here after calculation.</div><button id="createBooking" class="btn btn-dark mt-3" type="button" hidden><?= e($t('book')) ?></button><div id="bookingResult" class="mt-3" role="status" aria-live="polite"></div></section></div><?php endif; ?></main><?php include __DIR__.'/includes/footer.php';
